function regionalizeBhs(english: string, translation: string, locale: Locale) {
  if (locale === "hr" && croatianOverrides[english]) return croatianOverrides[english];
  if (locale === "sr" && serbianOverrides[english]) return serbianOverrides[english];
  const replacements = locale === "hr" ? croatianReplacements : locale === "sr" ? serbianReplacements : [];
  return replacements.reduce((value, [pattern, replacement]) => value.replace(pattern, replacement), translation);
}

const localeColumn: Record<Locale, number> = { en: 0, bs: 1, hr: 1, sr: 1, de: 2, es: 3, fr: 4, nl: 5 };
const maps = Object.fromEntries(
  supportedLocales.map(({ code }) => [
    code,
    new Map(rows.map((row) => [row[0], regionalizeBhs(row[0], row[localeColumn[code]], code)])),
  ]),
) as Record<Locale, Map<string, string>>;

export function isLocale(value: string | null): value is Locale {
  return supportedLocales.some((locale) => locale.code === value);
}

function preserveWhitespace(source: string, translated: string) {
  const leading = source.match(/^\s*/)?.[0] ?? "";
  const trailing = source.match(/\s*$/)?.[0] ?? "";
  return `${leading}${translated}${trailing}`;
}

export function translateText(source: string, locale: Locale) {
  if (locale === "en" || !source.trim()) return source;
  const trimmed = source.trim();
  const exact = maps[locale].get(trimmed);
  if (exact) return preserveWhitespace(source, exact);
  const dynamic = translateDynamicText(trimmed, locale);
  if (dynamic) return preserveWhitespace(source, dynamic);
  return source;
}

