function translateDynamicText(source: string, locale: Locale) {
  if (locale === "en") return null;
  const categoryMatch = source.match(/^The wording matches a common (.+) pattern\.$/);
  if (categoryMatch) {
    const category = [...maps[locale].entries()].find(([english]) => english.toLowerCase() === categoryMatch[1])?.[1] ?? categoryMatch[1];
    const templates: Record<Exclude<Locale, "en">, string> = {
      bs: `Tekst odgovara čestom obrascu: ${category}.`,
      hr: `Tekst odgovara čestom obrascu: ${category}.`,
      sr: `Tekst odgovara čestom obrascu: ${category}.`,
      de: `Der Text entspricht einem häufigen Muster: ${category}.`,
      es: `El texto coincide con un patrón frecuente: ${category}.`,
      fr: `Le texte correspond à un schéma courant : ${category}.`,
      nl: `De tekst past bij een veelvoorkomend patroon: ${category}.`,
    };
    return regionalizeBhs(source, templates[locale], locale);
  }

  const column = localeColumn[locale] - 1;
  for (const [pattern, templates] of dynamicRows) {
    const match = source.match(pattern);
    if (match) {
      const translated = templates[column].replace(/\$(\d)/g, (_, index: string) => match[Number(index)] ?? "");
      return regionalizeBhs(source, translated, locale);
    }
  }
  return null;
}
